/**
 * Consultation submit API - shared contract (framework independent).
 *
 * Success body (unchanged, backward compatible):
 *   { ok: true, crm_record_id, deduplicated }
 * Error body (superset of the legacy `{ error_code }`):
 *   { ok: false, error_code, issues? }   - `issues` carries paths and codes only, never values.
 */

/** `cns_` + hex/dash id generated by the browser (`crypto.randomUUID`). */
export const SUBMISSION_ID_PATTERN = /^cns_[0-9a-f-]{20,80}$/i;

/** Default request body limit. The measured worst-case v2.1.0 payload is ~30 KB. */
export const DEFAULT_MAX_BODY_BYTES = 128 * 1024;

export type ConsultErrorCode =
  | "METHOD_NOT_ALLOWED"
  | "UNSUPPORTED_MEDIA_TYPE"
  | "PAYLOAD_TOO_LARGE"
  | "INVALID_JSON"
  | "INVALID_IDEMPOTENCY_KEY"
  | "UNSUPPORTED_FORM_VERSION"
  | "INVALID_PAYLOAD"
  | "OUTCOME_MISMATCH"
  | "SUBMISSION_CONFLICT"
  | "STAGING_ONLY"
  | "STAGING_UNAVAILABLE"
  | "STORAGE_UNAVAILABLE";

export const ERROR_STATUS: Record<ConsultErrorCode, number> = {
  METHOD_NOT_ALLOWED: 405,
  UNSUPPORTED_MEDIA_TYPE: 415,
  PAYLOAD_TOO_LARGE: 413,
  INVALID_JSON: 400,
  INVALID_IDEMPOTENCY_KEY: 400,
  UNSUPPORTED_FORM_VERSION: 400,
  INVALID_PAYLOAD: 400,
  OUTCOME_MISMATCH: 422,
  SUBMISSION_CONFLICT: 409,
  STAGING_ONLY: 403,
  STAGING_UNAVAILABLE: 503,
  STORAGE_UNAVAILABLE: 503,
};

export type ValidationIssue = { path: string; code: string };

export type ConsultSuccessBody = {
  ok: true;
  crm_record_id: string;
  deduplicated: boolean;
};

export type ConsultErrorBody = {
  ok: false;
  error_code: ConsultErrorCode;
  issues?: ValidationIssue[];
};

export type ConsultResult = {
  status: number;
  body: ConsultSuccessBody | ConsultErrorBody;
  headers?: Record<string, string>;
};

export function errorResult(
  code: ConsultErrorCode,
  extra: { issues?: ValidationIssue[]; headers?: Record<string, string> } = {},
): ConsultResult {
  const body: ConsultErrorBody = { ok: false, error_code: code };
  if (extra.issues && extra.issues.length > 0) body.issues = extra.issues;
  const result: ConsultResult = { status: ERROR_STATUS[code], body };
  if (extra.headers) result.headers = extra.headers;
  return result;
}
